function findMaximumNumber(k, x) {
  // Total price of every number from 1 to num, stopping early once it passes k.
  function accumulatedPrice(num) {
    let total = 0;
    for (let bit = x - 1; 2 ** bit <= num; bit += x) {
      const half = 2 ** bit;
      const block = 2 * half;
      const fullBlocks = Math.floor((num + 1) / block);
      const rest = (num + 1) % block;
      total += fullBlocks * half + Math.max(0, rest - half);
      if (total > k) break;
    }
    return total;
  }

  let low = 1;
  let high = 2 * k + 2 ** x;
  while (low < high) {
    const mid = low + Math.ceil((high - low) / 2);
    if (accumulatedPrice(mid) <= k) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

