function findMaximumNumber(k, x) {
  // Walk the numbers one by one, adding each price until the budget is broken.
  let total = 0;
  for (let num = 1; ; num++) {
    const bits = num.toString(2).split('').reverse();
    for (let pos = x; pos <= bits.length; pos += x) {
      if (bits[pos - 1] === '1') total++;
    }
    if (total > k) return num - 1;
  }
}

